import argparse
from pathlib import Path

class Options:
    def __init__(self):
        self.parser = argparse.ArgumentParser(description='MaSS training and depth evaluation')
        self.parser.add_argument('--data_path', type=str, help='path to the training data', required=True)
        self.parser.add_argument('--log_dir', type=str, help='log directory', default='tmp')
        self.parser.add_argument('--device_id', type=int, help='gpu number', default=0)
        self.parser.add_argument('--vis_device_id', type=int, help='visible gpu number', default=0)
        self.parser.add_argument('--baseline', type=str, choices=['mass'], help='the name of the folder to save the model in', default='mass')
        self.parser.add_argument('--model_name', type=str, help='the name of the folder to save the model in', default='mass_mix')
        self.parser.add_argument('--split', type=str, help='Comma-separated list of dataset splits to use', default='eigen_zhou_pp')
        self.parser.add_argument('--model', type=str, help='which model to load', choices=['lite-mono'], default='lite-mono')
        self.parser.add_argument('--weight_decay', type=float, help='weight decay in AdamW', default=0.01)
        self.parser.add_argument('--num_layers', type=int, help='number of resnet layers', default=18, choices=[18])
        self.parser.add_argument('--dataset', type=str, help='dataset to train on', default='kitti_pp')
        self.parser.add_argument('--png', help='if set, trains from raw KITTI png files (instead of jpgs)', action='store_true')
        self.parser.add_argument('--height', type=int, help='input image height', default=384)
        self.parser.add_argument('--width', type=int, help='input image width', default=640)
        self.parser.add_argument('--disparity_smoothness', type=float, help='disparity smoothness weight', default=0.001)
        self.parser.add_argument('--scales', nargs='+', type=int, help='scales used in the loss', default=[0, 1, 2])
        self.parser.add_argument('--min_depth', type=float, help='minimum depth', default=0.1)
        self.parser.add_argument('--max_depth', type=float, help='maximum depth', default=80.0)
        self.parser.add_argument('--frame_ids', nargs='+', type=int, help='frames to load', default=[0, -1, 1])
        self.parser.add_argument('--batch_size', type=int, help='batch size', default=6)
        self.parser.add_argument('--lr', nargs='+', type=float, help='learning rates of DepthNet and PoseNet. Initial learning rate, minimum learning rate, First cycle step size.', default=[0.0001, 5e-06, 31, 0.0001, 1e-05, 31])
        self.parser.add_argument('--num_epochs', type=int, help='number of epochs', default=50)
        self.parser.add_argument('--v1_multiscale', help='if set, uses monodepth v1 multiscale', action='store_true')
        self.parser.add_argument('--avg_reprojection', help='if set, uses average reprojection loss', action='store_true')
        self.parser.add_argument('--disable_automasking', help="if set, doesn't do auto-masking", action='store_true')
        self.parser.add_argument('--no_ssim', help='if set, disables ssim in the loss', action='store_true')
        self.parser.add_argument('--mypretrain', type=str, help='if set, use my pretrained encoder')
        self.parser.add_argument('--no_cuda', help='if set disables CUDA', action='store_true')
        self.parser.add_argument('--num_workers', type=int, help='number of dataloader workers', default=6)
        self.parser.add_argument('--load_weights_folder', type=str, help='name of model to load')
        self.parser.add_argument('--models_to_load', nargs='+', type=str, help='models to load', default=['encoder', 'depth', 'pose_encoder', 'pose'])
        self.parser.add_argument('--log_frequency', type=int, help='number of batches between each tensorboard log', default=100)
        self.parser.add_argument('--save_frequency', type=int, help='number of epochs between each save', default=1)
        self.parser.add_argument('--gt_height', type=int, help='input image height', default=900)
        self.parser.add_argument('--gt_width', type=int, help='input image width', default=1600)
        self.parser.add_argument('--disable_median_scaling', help='if set disables median scaling in evaluation', action='store_true')
        self.parser.add_argument('--pred_depth_scale_factor', help='if set multiplies predictions by this number', type=float, default=1)
        self.parser.add_argument('--eval_split', type=str, default='eigen', help='which split to run eval on')
        self.parser.add_argument('--save_pred_disps', help='if set saves predicted disparities', action='store_true')
        self.parser.add_argument('--eval_out_dir', help='if set will output the disparities to this folder', type=str)
        self.parser.add_argument('--post_process', help='if set will perform the flipping post processing from the original monodepth paper', action='store_true')
        self.parser.add_argument('--contrast_weights', type=float, default=0.05)
        self.parser.add_argument('--contrastive_learning', action='store_true', help='use contrastive_learning')
        self.parser.add_argument('--psedo_weights', type=float, default=0.01)
        self.parser.add_argument('--psedo_depth', choices=['psedo_depth'], default='psedo_depth', help='Legacy spelling retained for the prepared pseudo-depth directory')
        self.parser.add_argument('--dino_weights', default=str(Path(__file__).resolve().parent / 'weights/dinov2_vitb14_reg4_pretrain.pth'))
        self.parser.add_argument('--gt_path', help='Ground-truth directory; defaults to <data_path>/depth')
        self.parser.add_argument('--max_steps', type=int, default=0, help='Stop training after this many optimizer steps; 0 runs all epochs')
        self.parser.add_argument('--eval_height', type=int, help='Evaluation input height; defaults to checkpoint metadata')
        self.parser.add_argument('--eval_width', type=int, help='Evaluation input width; defaults to checkpoint metadata')

    def parse(self, args=None):
        return self.parser.parse_args(args)
